export const DETTES_KARMIQUES_TEXTES = {
  13: { titre: 'Dette 13 — Le Travail comme chemin',    corps: `La dette du 13 indique une tendance héritée à éviter l'effort, à chercher des voies rapides là où seul le travail patient ouvre réellement la porte. Ce n'est pas un jugement — c'est une invitation à découvrir que l'effort soutenu dans un domaine qui t'importe peut être une source de fierté profonde, pas une punition.` },
  14: { titre: 'Dette 14 — La Tempérance comme sagesse', corps: `La dette du 14 pointe vers une tendance aux extrêmes — trop ou pas assez, tout de suite ou jamais. Cette vie t'invite à expérimenter le juste milieu non comme une capitulation mais comme une forme de sagesse. La modération n'est pas l'ennemi de l'intensité — c'est ce qui lui permet de durer.` },
  16: { titre: `L'Ego comme obstacle`,                  corps: `La dette du 16 signale une tendance à construire ton identité sur des bases fragiles — statut, image, rôle social — qui s'effondrent tôt ou tard. Ces effondrements sont des libérations déguisées : chaque fois qu'une construction artificielle tombe, quelque chose de plus authentique peut émerger.` },
  19: { titre: `Le Pouvoir au service de l'autre`,      corps: `La dette du 19 indique une tendance à abuser de l'influence ou à attendre que les autres fassent ce que tu devrais faire toi-même. C'est une invitation à expérimenter ce que cela fait d'utiliser ta force pour élever plutôt que pour dominer.` },
};

// ── Assembleur de contenu ──────────────────────────────────────────────────
export function assemblerContenu(profil) {
  return {
    cheminDeVie:   CHEMINS_DE_VIE[profil.cheminDeVie]          || CHEMINS_DE_VIE[1],
    expression:    EXPRESSIONS[profil.expression]               || EXPRESSIONS[1],
    ame:           AMES[profil.ame]                             || AMES[1],
    personnalite:  PERSONNALITES[profil.personnalite]           || PERSONNALITES[1],
    anneePerso:    ANNEES_PERSONNELLES[profil.anneePersonnelle] || ANNEES_PERSONNELLES[1],
    signe:         SIGNES_ASTRO[profil.signe]                   || SIGNES_ASTRO['Bélier'],
    planete:       PLANETES_TEXTES[profil.planete?.nom]         || PLANETES_TEXTES['Soleil'],
    lecons:        profil.nombresAbsents.map(n => ({ numero: n, ...LECONS_KARMIQUES[n] })),
    dettes:        profil.dettesKarmiques.map(d => ({ numero: d, ...DETTES_KARMIQUES_TEXTES[d] })),
    synthese:      genererSynthese(profil),
  };
}

// ── Synthèse cross-disciplinaire ───────────────────────────────────────────
const QUALITE_NOMBRE = {
  1:  { polarite: 'yang', theme: 'initiative',    element_num: 'Feu'  },
  2:  { polarite: 'yin',  theme: 'réceptivité',   element_num: 'Eau'  },
  3:  { polarite: 'yang', theme: 'expression',    element_num: 'Air'  },
  4:  { polarite: 'yin',  theme: 'structure',     element_num: 'Terre'},
  5:  { polarite: 'yang', theme: 'liberté',       element_num: 'Air'  },
  6:  { polarite: 'yin',  theme: 'harmonie',      element_num: 'Terre'},
  7:  { polarite: 'yin',  theme: 'profondeur',    element_num: 'Eau'  },
  8:  { polarite: 'yang', theme: 'puissance',     element_num: 'Terre'},
  9:  { polarite: 'yang', theme: 'universalité',  element_num: 'Feu'  },
  11: { polarite: 'yin',  theme: 'illumination',  element_num: 'Eau'  },
  22: { polarite: 'yang', theme: 'manifestation', element_num: 'Terre'},
  33: { polarite: 'yang', theme: 'service',       element_num: 'Feu'  },
};

export function genererSynthese(profil) {
  const { cheminDeVie, expression, ame, element, arcaneVie, arcaneAnnee, anneePersonnelle, nombresAbsents, dettesKarmiques, signe, modalite } = profil;
  const qCdV  = QUALITE_NOMBRE[cheminDeVie]  || QUALITE_NOMBRE[1];
  const qExpr = QUALITE_NOMBRE[expression]   || QUALITE_NOMBRE[1];
  const qAme  = QUALITE_NOMBRE[ame]          || QUALITE_NOMBRE[1];
  const convergences = [];
  const tensions     = [];

  if (qCdV.element_num === element) {
    convergences.push(`Ton chemin de vie ${cheminDeVie} (${qCdV.theme}) et ton signe ${signe} partagent tous deux l'énergie de l'élément ${element} — une cohérence profonde entre ce que tu es venu accomplir et la façon dont tu es naturellement câblé pour avancer. Cette convergence élémentaire est rare et significative : les efforts faits dans l'axe de ton chemin de vie se sentent naturels plutôt que forcés.`);
  }
  if (qCdV.polarite === qAme.polarite) {
    convergences.push(`Ton chemin de vie (${cheminDeVie}) et les aspirations profondes de ton âme (${ame}) ont la même polarité ${qCdV.polarite} — ce que tu désires au fond de toi est bien aligné avec ce que tu es venu apprendre. Moins de friction interne, plus d'énergie disponible pour avancer dans ta direction propre.`);
  }
  if (arcaneVie.numero === arcaneAnnee.numero) {
    convergences.push(`Ton Arcane de Vie et ton Arcane de l'Année sont identiques (${arcaneVie.nom}) — une synchronicité rare qui indique que cette période de ta vie résonne profondément avec ta mission fondamentale. Ce que tu traverses maintenant n'est pas un détour — c'est le chemin lui-même.`);
  }
  if (qCdV.polarite === 'yang' && (element === 'Eau' || element === 'Terre')) {
    tensions.push(`Ton chemin de vie ${cheminDeVie} (${qCdV.theme}, énergie active et directrice) est porté par un signe de ${element}, naturellement plus réceptif et intériorisé. Cette tension productive t'invite à ne pas choisir entre agir et sentir — mais à apprendre à initier depuis ton intérieur plutôt que malgré lui.`);
  }
  if (qCdV.polarite === 'yin' && element === 'Feu') {
    tensions.push(`Ton chemin de vie ${cheminDeVie} (énergie réceptive et intérieure) est porté par un signe de Feu (${signe}), naturellement tourné vers l'action. Cette tension te demande d'apprendre à honorer ton besoin de retrait sans laisser ton feu naturel s'éteindre par excès de prudence.`);
  }
  if (qCdV.theme !== qExpr.theme && qCdV.polarite !== qExpr.polarite) {
    tensions.push(`Ton chemin de vie (${cheminDeVie} — ${qCdV.theme}) et ton nombre d'expression (${expression} — ${qExpr.theme}) ne vibrent pas dans le même registre. Ce que tu es venu faire dans cette vie et l'image que tu projettes naturellement peuvent parfois sembler contradictoires. Cette distance n'est pas un problème — c'est une invitation à les réconcilier consciemment.`);
  }
  if (modalite === 'Fixe' && [5, 9].includes(cheminDeVie)) {
    tensions.push(`Ton signe de modalité Fixe aime la constance et la fidélité aux engagements — mais ton chemin de vie ${cheminDeVie} t'appelle à embrasser le mouvement et la transformation. Cette friction est l'une des plus fécondes de ta carte : elle te demande d'apprendre à changer sans perdre ta colonne vertébrale.`);
  }

  let texteDettes = '';
  if (dettesKarmiques.length > 0) {
    const nomsDettes = dettesKarmiques.map(d => `${d} (${DETTES_KARMIQUES_TEXTES[d]?.titre || ''})`).join(' et ');
    texteDettes = `Sur le plan karmique, la présence de la dette ${nomsDettes} dans tes calculs indique un domaine spécifique que cette incarnation t'invite à nettoyer. Ce n'est pas un fardeau — c'est une précision : là où d'autres avancent à l'intuition, tu as une invitation claire à un travail conscient.`;
  }

  const portrait = genererPortrait(profil, convergences, tensions);
  return { convergences, tensions, texteDettes, portrait };
}

function genererPortrait(profil, convergences, tensions) {
  const { prenom, cheminDeVie, signe, element, arcaneVie, anneePersonnelle } = profil;
  const qCdV = QUALITE_NOMBRE[cheminDeVie] || QUALITE_NOMBRE[1];
  const anneeTitre = ANNEES_PERSONNELLES[anneePersonnelle]?.titre || '';
  const filConvergences = convergences.length > 0
    ? `Plusieurs disciplines convergent pour te dire la même chose : ${qCdV.theme} est le fil rouge de cette incarnation.`
    : `Différentes énergies traversent cette incarnation, créant une richesse de nuances que tu es invité à embrasser plutôt qu'à résoudre.`;
  return `${prenom}, ce portrait croise quatre systèmes de lecture différents — et leur accord ou leur tension est en soi une information précieuse. Ton chemin de vie ${cheminDeVie} (${CHEMINS_DE_VIE[cheminDeVie]?.titre || ''}) dessine la direction fondamentale de cette vie. Ton signe ${signe} (${element}) colore la façon dont tu avances naturellement. L'Arcane ${arcaneVie.nom} nomme le mythe intérieur qui opère dans ton histoire. Et l'année personnelle ${anneePersonnelle} — ${anneeTitre} — précise l'invitation du moment présent. ${filConvergences} Ce rapport n'est pas une vérité gravée dans le marbre, mais un miroir : prends ce qui résonne, laisse ce qui ne te parle pas, et utilise-le comme point de départ d'une conversation plus profonde avec toi-même.`;
}
